using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace StudentHousing.Api;
public record PropertyInput(string Title,string Description,string Address,string District,string Ward,decimal Price,decimal Area,int[] AmenityIds);
[ApiController,Route("api/properties")]
public class PropertiesController(HousingDb db):ControllerBase {
 [HttpGet] public async Task<IActionResult> Search([FromQuery]string? keyword,[FromQuery]string? district,[FromQuery]decimal? minPrice,[FromQuery]decimal? maxPrice,[FromQuery]decimal? minArea,[FromQuery]decimal? maxArea,[FromQuery]int[]? amenityIds,[FromQuery]string sort="newest",[FromQuery]int page=1,[FromQuery]int pageSize=12){if(page<1||pageSize<1||pageSize>50||minPrice<0||minArea<0||maxPrice<minPrice||maxArea<minArea)return BadRequest(new{error="Bộ lọc không hợp lệ"});IQueryable<Property> q=db.Properties.AsNoTracking().Where(x=>x.Status==PropertyStatus.Active);if(!string.IsNullOrWhiteSpace(keyword))q=q.Where(x=>x.Title.Contains(keyword));if(!string.IsNullOrWhiteSpace(district))q=q.Where(x=>x.District==district);if(minPrice.HasValue)q=q.Where(x=>x.Price>=minPrice);if(maxPrice.HasValue)q=q.Where(x=>x.Price<=maxPrice);if(minArea.HasValue)q=q.Where(x=>x.Area>=minArea);if(maxArea.HasValue)q=q.Where(x=>x.Area<=maxArea);foreach(var id in (amenityIds??[]).Distinct())q=q.Where(x=>x.PropertyAmenities.Any(a=>a.AmenityId==id));var total=await q.CountAsync();q=sort switch{"price_asc"=>q.OrderBy(x=>x.Price),"price_desc"=>q.OrderByDescending(x=>x.Price),_=>q.OrderByDescending(x=>x.CreatedAt)};var items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.Title,x.Address,x.District,x.Price,x.Area,x.CreatedAt,Image=x.Images.OrderBy(i=>i.DisplayOrder).Select(i=>i.ImageUrl).FirstOrDefault(),Amenities=x.PropertyAmenities.Select(a=>a.Amenity.Name)}).ToListAsync();return Ok(new{items,page,pageSize,totalItems=total,totalPages=(int)Math.Ceiling((double)total/pageSize)});}
 [HttpGet("{id:int}")] public async Task<IActionResult> Detail(int id){var p=await db.Properties.AsNoTracking().Where(x=>x.Id==id&&x.Status==PropertyStatus.Active).Select(x=>new{x.Id,x.Title,x.Description,x.Address,x.District,x.Ward,x.Price,x.Area,x.CreatedAt,Images=x.Images.OrderBy(i=>i.DisplayOrder).Select(i=>i.ImageUrl),Amenities=x.PropertyAmenities.Select(a=>new{a.Amenity.Id,a.Amenity.Name})}).FirstOrDefaultAsync();return p==null?NotFound():Ok(p);}
 [Authorize(Roles="Landlord"),HttpPost] public async Task<IActionResult> Create(PropertyInput d){if(!Valid(d))return BadRequest(new{error="Dữ liệu phòng không hợp lệ"});var p=Map(d);p.LandlordId=Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);db.Properties.Add(p);await db.SaveChangesAsync();return Created($"/api/properties/{p.Id}",new{p.Id,p.Status});}
 [Authorize(Roles="Landlord"),HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,PropertyInput d){var uid=Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var p=await db.Properties.Include(x=>x.PropertyAmenities).SingleOrDefaultAsync(x=>x.Id==id&&x.LandlordId==uid);if(p==null)return NotFound();if(!Valid(d))return BadRequest(new{error="Dữ liệu phòng không hợp lệ"});if(p.Status==PropertyStatus.Rented)return Conflict(new{error="Tin đã cho thuê"});p.Title=d.Title;p.Description=d.Description;p.Address=d.Address;p.District=d.District;p.Ward=d.Ward;p.Price=d.Price;p.Area=d.Area;p.Status=PropertyStatus.Pending;p.UpdatedAt=DateTime.UtcNow;p.PropertyAmenities.Clear();foreach(var a in d.AmenityIds.Distinct())p.PropertyAmenities.Add(new PropertyAmenity{AmenityId=a});await db.SaveChangesAsync();return Ok(new{p.Id,p.Status});}
 [Authorize(Roles="Landlord"),HttpPatch("{id:int}/mark-rented")] public async Task<IActionResult> MarkRented(int id){var uid=Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var p=await db.Properties.SingleOrDefaultAsync(x=>x.Id==id&&x.LandlordId==uid);if(p==null)return NotFound();if(p.Status!=PropertyStatus.Active)return Conflict(new{error="Chỉ có thể đánh dấu tin đang hiển thị"});p.Status=PropertyStatus.Rented;p.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(new{p.Id,p.Status});}
 static bool Valid(PropertyInput d)=>!string.IsNullOrWhiteSpace(d.Title)&&!string.IsNullOrWhiteSpace(d.Address)&&!string.IsNullOrWhiteSpace(d.District)&&d.Price>0&&d.Area>0&&d.AmenityIds!=null;
 static Property Map(PropertyInput d)=>new(){Title=d.Title,Description=d.Description,Address=d.Address,District=d.District,Ward=d.Ward,Price=d.Price,Area=d.Area,PropertyAmenities=d.AmenityIds.Distinct().Select(id=>new PropertyAmenity{AmenityId=id}).ToList()};
}
